/**
 * Presets and clinic scenarios for PackedLayoutExplorer: plain data for each
 * lesson use of the explorer, plus the five debugging scenarios whose logs are
 * regenerated by the model in sv-aggregate-layout-model.ts.
 *
 * No React here. Every prediction option carries feedback that names the
 * misconception behind it and the IEEE 1800-2023 clause that decides it. The
 * tests in tests/lib/sv-aggregate-scenarios.test.ts check that every option
 * marked correct agrees with what the model computes.
 */

import {
  CMD_T_ENUM,
  OPCODE_E,
  assignPattern,
  assignWhole,
  assignmentLegality,
  enumCast,
  enumInitialValue,
  enumMemberReadout,
  enumName,
  fillWhole,
  formatD,
  formatH,
  formatSizedHex,
  memberRanges,
  randMemberCard,
  readMember,
  reorderMembers,
  structInitialValue,
  svDec,
  svHex,
  writeMember,
  type WholeAssign,
  type EnumSpec,
  type PackedMember,
  type TaggedMember,
  type TaggedUnionType,
  type TypeRef,
  type UnionType,
} from "@/lib/sv-aggregate-layout-model";
import type { SvValue } from "@/lib/sv-expression-model";

// ---------------------------------------------------------------------------
// Shared option shape
// ---------------------------------------------------------------------------

export interface ChoiceOption {
  id: string;
  label: string;
  correct: boolean;
  /** Diagnoses the misconception behind this choice, or confirms the rule. */
  feedback: string;
}

export interface Prediction {
  question: string;
  options: ChoiceOption[];
}

// ---------------------------------------------------------------------------
// Struct presets
// ---------------------------------------------------------------------------

export type StructPresetId = "cmd_t" | "ctrl_reg_t" | "frame_t" | "pkt_hdr_t" | "reversed" | "narrow-assign" | "enum-field";

export type StructAction =
  /** `fill` marks a fill literal such as '0, which takes its size from the assignment (§5.7.1) instead of being a value of `value`'s width. */
  | { kind: "whole"; value: SvValue; fill?: boolean }
  | { kind: "member"; member: string; value: SvValue }
  | { kind: "pattern"; fields: Record<string, SvValue> };

export interface StructStatement {
  /** The statement as the lesson writes it. */
  code: string;
  action: StructAction;
  /**
   * The variable this statement writes when it is not the preset's (the kata
   * declares `pkt_hdr_t hdr, rx;`). The strip and status take this name once
   * the statement has run. Such a statement must write the whole value (a
   * whole-vector or pattern write), so nothing of the previous variable's
   * value is carried over into the new one.
   */
  varName?: string;
  /** When present, the statement runs only after the learner commits a prediction. */
  prediction?: Prediction;
  /** Shown once the statement has run. */
  note?: string;
}

export interface StructPreset {
  id: StructPresetId;
  label: string;
  typeName: string;
  varName: string;
  members: readonly PackedMember[];
  statements: readonly StructStatement[];
  summary: string;
  /** Where the preset comes from, in the learner's words: shown beside the typedef, and true on any page that embeds the explorer. */
  source: string;
}

/** The lesson's title and a section of it. */
const fromLesson = (section: string): string => `Structs, Unions and Enums: ${section}`;

const logic = (id: string, width: number): PackedMember => ({ id, name: id, width, type: { kind: "logic" } });

