export const structPreset = (id?: string): StructPreset => STRUCT_PRESETS.find((p) => p.id === id) ?? STRUCT_PRESETS[0];

/**
 * The variable the strip and status name after `applied` statements have run:
 * the preset's, unless the last statement that ran names its own (the kata's
 * `rx`). A statement without a name writes the preset's variable.
 */
export function currentVarName(preset: StructPreset, applied: number): string {
  const last = preset.statements[Math.min(applied, preset.statements.length) - 1];
  return (applied > 0 ? last?.varName : undefined) ?? preset.varName;
}

/** A whole-vector statement run by the model: a fill literal takes the struct's own width (§5.7.1); any other value is extended or truncated to it (§10.7). */
export const runWholeAction = (members: readonly PackedMember[], action: Extract<StructAction, { kind: "whole" }>): WholeAssign => (action.fill ? fillWhole(members) : assignWhole(members, action.value));

/** Apply one statement to a struct value with the model's own write rules. */
export function applyStructAction(members: readonly PackedMember[], value: SvValue, action: StructAction): SvValue {
  switch (action.kind) {
    case "whole":
      return runWholeAction(members, action).value;
    case "member":
      return memberRanges(members).some((r) => r.name === action.member) ? writeMember(members, value, action.member, action.value).value : value;
    case "pattern":
      return assignPattern(members, action.fields);
  }
}

/** The value after running the first `count` statements of a preset, from the variable's Table 6-7 default. */
export function runStructStatements(preset: StructPreset, count: number, members: readonly PackedMember[] = preset.members): SvValue {
  let v = structInitialValue(members);
  preset.statements.slice(0, count).forEach((s) => {
    v = applyStructAction(members, v, s.action);
  });
  return v;
}

