export const VINT_THIRD_MEMBER: TaggedMember = { name: "Small", width: 8, typeText: "bit [7:0]", signed: false, fourState: false };

const TAGGED_ASSIGN_VALUES: Readonly<Record<string, { value: number; text: string }>> = {
  Valid: { value: 23, text: "23" },
  Small: { value: 0x5a, text: "8'h5A" },
};

/** The value a preset button assigns to a tagged member, undefined for a void member. */
export const taggedAssignValue = (m: TaggedMember): number | undefined => (m.width === null ? undefined : TAGGED_ASSIGN_VALUES[m.name]?.value);

/** The statement as written on its button and in the log. */
export const taggedAssignStatement = (m: TaggedMember): string => (m.width === null ? `v = tagged ${m.name};` : `v = tagged ${m.name} (${TAGGED_ASSIGN_VALUES[m.name]?.text});`);

/**
 * The predict gate before a tagged read. Two outcomes are stated by §11.9: the
 * read is legal when it is consistent with the tag, and a run-time error when it
 * is inconsistent with the tag. The third is derived: §11.9 also makes the tag
 * bits of an uninitialized variable undefined, so whether the check fires is not
 * defined, and the feedback labels that as derived.
 */
export const TAGGED_READ_PREDICTION = (memberRead: string, tagName: string | null): Prediction => {
  const matches = tagName !== null && memberRead.endsWith(`.${tagName}`);
  const mismatch = tagName !== null && !matches;
  const undefinedTag = tagName === null;
  return {
    question: `Is $display("%0d", ${memberRead}) legal now?`,
    options: [
      {
        id: "legal",
        label: "Legal: prints the value",
        correct: matches,
        feedback: matches
          ? `The tag is ${tagName}, so the read is consistent with it (§11.9).`
          : undefinedTag
            ? "The variable was never assigned: its tag bits are undefined (§11.9). Derived from that, there is no known tag for the read to be consistent with."
            : `The tag is ${tagName}; a member read must be consistent with the current tag (§11.9).`,
      },
      {
        id: "error",
        label: "Run-time error: the tag is another member",
        correct: mismatch,
        feedback: mismatch
          ? `Reading a member that does not match the current tag (${tagName}) is a run-time error (§11.9). The tag changes only through a tagged expression (§7.3.2).`
          : undefinedTag
            ? "The error is for a read inconsistent with the tag, and here the tag bits were never assigned. Derived: §11.9 makes the tag bits undefined, so whether the check fires is not defined."
            : `The tag is ${tagName}, which matches the member being read, so the read is legal (§11.9).`,
      },
      {
        id: "undefined",
        label: "Undefined: never assigned, so no defined result (derived from §11.9)",
        correct: undefinedTag,
        feedback: undefinedTag
          ? "An uninitialized tagged union is undefined, its tag bits included (§11.9). Derived from that, whether the check fires is not defined, so the read has no defined result. Assign a tagged expression first."
          : `The variable has been assigned: its tag is ${tagName}, a defined value, so the read is ${matches ? "legal" : "a run-time error"} (§11.9).`,
      },
    ],
  };
};

// ---------------------------------------------------------------------------
// Debug clinic
// ---------------------------------------------------------------------------

export type FixId = "reorder" | "logic-base" | "cast-check" | "package-typedef" | "rand-whole";

export interface ClinicFix {
  id: FixId;
  label: string;
}

export const CLINIC_FIXES: readonly ClinicFix[] = [
  { id: "reorder", label: "Reorder the members" },
  { id: "logic-base", label: "4-state enum base" },
  { id: "cast-check", label: "$cast with a check" },
  { id: "package-typedef", label: "One typedef in a package" },
  { id: "rand-whole", label: "rand on the whole struct" },
];

export interface ClinicLine {
  key: string;
  text: string;
  /** What the learner is told when they pick this line as the suspect. */
  whenPicked: string;
}

export interface ClinicRun {
  log: string[];
  /** True when the symptom is gone. */
  fixed: boolean;
  /** The fix removed the symptom as reported but the bug remains and now shows somewhere else, here at run time. */
  moved?: boolean;
  verdict: string;
}

export type ClinicScenarioId = "swapped-fields" | "idle-without-reset" | "empty-name" | "empty-name-struct" | "two-typedefs" | "rand-packed-member";

export interface ClinicScenario {
  id: ClinicScenarioId;
  title: string;
  /** The symptom in one sentence. */
  symptom: string;
  clause: string;
  lines: readonly ClinicLine[];
  /** The lines that count as the suspect; the first is the one "Show the suspect" marks. */
  suspectKeys: readonly string[];
  causes: readonly ChoiceOption[];
  correctFix: FixId;
  /** Why each fix does or does not remove the symptom. */
  fixFeedback: Readonly<Record<FixId, string>>;
  /** The change each fix would make here, in this scenario's own types, so the right fix cannot be found by matching names. */
  fixCode: Readonly<Record<FixId, string>>;
  hints: readonly [string, string, string];
  /** The model regenerates the log for the given fix (null = as found). */
  run: (fix: FixId | null) => ClinicRun;
}

const WRONG_ORDER_CMD_T: readonly PackedMember[] = [logic("data", 16), logic("addr", 12), logic("op", 4)];

const ST_E_INT: EnumSpec = { name: "st_e", baseDecl: "", states: 2, width: 32, members: [{ name: "IDLE", value: 0 }, { name: "RUN", value: 1 }, { name: "DONE", value: 2 }] };
const ST_E_LOGIC: EnumSpec = { ...ST_E_INT, baseDecl: "logic [1:0]", states: 4, width: 2 };

const EXPECTED = { op: svHex(4, "2"), addr: svHex(12, "123"), data: svHex(16, "BEEF") };

const noChange = "This change does not touch the cause, so the symptom stays.";

/**
 * A log line that starts with this is the model's note, not simulator output:
 * a log otherwise shows only what a $display in the listing prints.
 */
export const CLINIC_NOTE_PREFIX = "// ";

/** $error prints a tool-specific message that includes the user's text (§20.10), so the log names the text and not a prefix. */
const errorNote = (text: string): string => `$error reports "${text}" in a tool-specific message (§20.10)`;

